int main(void)
{
	RCC_AHB1ENR_t volatile *const pRccRegister = RCC_AHB1ENR_REG;
	GPIOx_MODE_t volatile *const pPortDModeRegister = GPIOD_MODE_REG;
	GPIOx_ODR_t volatile *const pPortDOutRegister = GPIOD_ODR_REG;

	//1. Enable RSS Clock for GPIOD in AHB1ENR (SET the 3rd bit position)
	//*pClkCtrlreg |= (1 << 3);
	pRccRegister->gpioD_en = CLOCK_ENABLE;

	//2. configure the mode of the IO pin as output
	//a. clear the 24th and 25th bit positions (CLEAR)
	//*pPortDModeReg &= ~(3 << 24);
	pPortDModeRegister->moder_12 = 0x00;
	pPortDModeRegister->moder_12 = MODE_CONF_OUTPUT;
	//b. make 24th bit position as 1 (SET)
	//*pPortDModeReg |= (1 << 24);
	pPortDOutRegister->odr_12 = PIN_STATE_HIGH;

	//3. SET 12th bit of the output data register to make IO pin-12 HIGH
	//*pPortDOutReg |= (1 << 12);

    /* Loop forever */
	while(1){
		//*pPortDOutReg |= (1 << 12);
		pPortDOutRegister->odr_12 = PIN_STATE_HIGH;

		for(int i = 0; i <= DELAY_COUNT; i++);

		//*pPortDOutReg &= ~(1 << 12);
		pPortDOutRegister->odr_12 = PIN_STATE_LOW;

		for(int i = 0; i <= DELAY_COUNT; i++);
	}
}
